var recalculateCustomerBalance = async (db = query, customerId) => {
  await db(
    `
    UPDATE customers c
    SET balance = COALESCE(c.opening_balance, 0) + COALESCE((
      SELECT SUM(outstanding)
      FROM (
        SELECT
          CASE
            -- \u0627\u0644\u0645\u0628\u064A\u0639\u0627\u062A \u0627\u0644\u0645\u0631\u062A\u062C\u0639\u0629: \u0631\u0635\u064A\u062F\u0647\u0627 \u0635\u0641\u0631 (\u062A\u0645 \u0627\u0644\u0627\u0633\u062A\u0631\u062F\u0627\u062F)
            WHEN s.status = 'returned' THEN 0
            ELSE
              COALESCE(s.total_amount, 0) - COALESCE((
                SELECT SUM(amount)
                FROM payments p
                WHERE p.reference_type = 'sale'
                  AND p.reference_id = s.id
              ), 0)
          END AS outstanding
        FROM sales s
        WHERE s.customer_id = $1
          AND s.deleted_at IS NULL
          AND s.sale_type = 'wholesale'
          AND s.status IN ('completed', 'returned')

        UNION ALL

        SELECT
          COALESCE(i.total_amount, 0) - COALESCE((
            SELECT SUM(amount)
            FROM payments p
            WHERE p.reference_type = 'invoice'
              AND p.reference_id = i.id
          ), 0) AS outstanding
        FROM invoices i
        WHERE i.customer_id = $1
          AND i.sale_id IS NULL
          AND i.deleted_at IS NULL
      ) source
    ), 0),
    current_balance = COALESCE(c.opening_balance, 0) + COALESCE((
      SELECT SUM(outstanding)
      FROM (
        SELECT
          CASE
            WHEN s.status = 'returned' THEN 0
            ELSE
              COALESCE(s.total_amount, 0) - COALESCE((
                SELECT SUM(amount)
                FROM payments p
                WHERE p.reference_type = 'sale'
                  AND p.reference_id = s.id
              ), 0)
          END AS outstanding
        FROM sales s
        WHERE s.customer_id = $1
          AND s.deleted_at IS NULL
          AND s.sale_type = 'wholesale'
          AND s.status IN ('completed', 'returned')

        UNION ALL

        SELECT
          COALESCE(i.total_amount, 0) - COALESCE((
            SELECT SUM(amount)
            FROM payments p
            WHERE p.reference_type = 'invoice'
              AND p.reference_id = i.id
          ), 0) AS outstanding
        FROM invoices i
        WHERE i.customer_id = $1
          AND i.sale_id IS NULL
          AND i.deleted_at IS NULL
      ) source
    ), 0)
    WHERE c.id = $1
    `,
    [customerId]
  );
};

