var importDailySales = async (rows, userId) => {
  const MAX_IMPORT = 500;
  if (rows.length > MAX_IMPORT) {
    throw new AppError(`\u0627\u0644\u062D\u062F \u0627\u0644\u0623\u0642\u0635\u0649 \u0644\u0644\u0627\u0633\u062A\u064A\u0631\u0627\u062F \u0647\u0648 ${MAX_IMPORT} \u0633\u0637\u0631 \u062F\u0641\u0639\u0629 \u0648\u0627\u062D\u062F\u0629`, 400);
  }
  const results = { success: 0, failed: [], total: rows.length };
  for (let i2 = 0; i2 < rows.length; i2++) {
    try {
      await createDailySale(rows[i2], userId);
      results.success++;
    } catch (err) {
      results.failed.push({ row: i2 + 2, message: err.message, data: rows[i2] });
    }
  }
  return results;
};

// src/services/salesExcelService.js
var import_xlsx2 = __toESM(require_xlsx(), 1);

// src/services/excelSecurity.js
var import_xlsx = __toESM(require_xlsx(), 1);
var MAX_EXCEL_BYTES = 5 * 1024 * 1024;
var MAX_SHEETS = 5;
var MAX_CELLS_PER_SHEET = 5e4;
var countSheetCells = (worksheet) => {
  if (!worksheet?.["!ref"]) return 0;
  const range = import_xlsx.default.utils.decode_range(worksheet["!ref"]);
  return (range.e.r - range.s.r + 1) * (range.e.c - range.s.c + 1);
};
var readSafeWorkbook = (buffer, options = {}) => {
  if (!Buffer.isBuffer(buffer)) {
    throw new AppError("Invalid Excel upload", 400);
  }
  if (buffer.length > MAX_EXCEL_BYTES) {
    throw new AppError("Excel file is too large", 400);
  }
  const workbook = import_xlsx.default.read(buffer, {
    type: "buffer",
    cellDates: Boolean(options.cellDates),
    cellFormula: false,
    cellHTML: false,
    cellNF: false,
    cellStyles: false,
    sheetRows: options.sheetRows || 5e3,
    WTF: false
  });
  if (!workbook.SheetNames.length) {
    throw new AppError("Excel file has no sheets", 400);
  }
  if (workbook.SheetNames.length > MAX_SHEETS) {
    throw new AppError("Excel file has too many sheets", 400);
  }
  for (const sheetName of workbook.SheetNames) {
    if (countSheetCells(workbook.Sheets[sheetName]) > MAX_CELLS_PER_SHEET) {
      throw new AppError("Excel sheet is too large", 400);
    }
  }
  return workbook;
};

// src/utils/numberParsing.js
var ARABIC_DIGITS = "\u0660\u0661\u0662\u0663\u0664\u0665\u0666\u0667\u0668\u0669";
var PERSIAN_DIGITS = "\u06F0\u06F1\u06F2\u06F3\u06F4\u06F5\u06F6\u06F7\u06F8\u06F9";
var normalizeLocalizedNumberText = (value) => {
  const text = String(value ?? "").replace(/[٠-٩]/g, (digit) => String(ARABIC_DIGITS.indexOf(digit))).replace(/[۰-۹]/g, (digit) => String(PERSIAN_DIGITS.indexOf(digit))).replace(/[\u200e\u200f\s]/g, "").replace(/٬/g, "").replace(/٫/g, ".").trim();
  if (!text) return "";
  const lastComma = text.lastIndexOf(",");
  const lastDot = text.lastIndexOf(".");
  if (lastComma === -1) return text;
  if (lastDot === -1) {
    return /^[-+]?\d{1,3}(,\d{3})+$/.test(text) ? text.replace(/,/g, "") : text.replace(/,/g, ".");
  }
  if (lastComma > lastDot) {
    return text.replace(/\./g, "").replace(/,/g, ".");
  }
  return text.replace(/,/g, "");
};
var parseLocalizedNumber = (value, fallback = NaN) => {
  if (typeof value === "number") return Number.isFinite(value) ? value : fallback;
  const parsed = Number(normalizeLocalizedNumberText(value));
  return Number.isFinite(parsed) ? parsed : fallback;
};

