      throw new AppError(`\u0627\u0644\u0633\u0637\u0631 ${idx + 1}: \u0627\u0644\u0643\u0645\u064A\u0629 \u064A\u062C\u0628 \u0623\u0646 \u062A\u0643\u0648\u0646 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0635\u0641\u0631`);
    if (!unit_code) throw new AppError(`\u0627\u0644\u0633\u0637\u0631 ${idx + 1}: \u064A\u062C\u0628 \u062A\u062D\u062F\u064A\u062F \u0648\u062D\u062F\u0629 \u0635\u062D\u064A\u062D\u0629`);
