var renderHtmlToPdf = async (html) => {
  const chromePath = resolveChromePath();
  if (!chromePath) {
    throw new Error("Chrome not found for PDF rendering");
  }
  const tempDir = await fs2.mkdtemp(path3.join(os.tmpdir(), "quote-pdf-"));
  const htmlPath = path3.join(tempDir, "quote.html");
  const pdfPath = path3.join(tempDir, "quote.pdf");
  await fs2.writeFile(htmlPath, html, "utf8");
  try {
    await execFileAsync(
      chromePath,
      [
        "--headless=new",
        "--disable-gpu",
        "--no-sandbox",
        "--disable-extensions",
        "--hide-scrollbars",
        "--run-all-compositor-stages-before-draw",
        "--virtual-time-budget=1200",
        "--print-to-pdf-no-header",
        `--print-to-pdf=${pdfPath}`,
        pathToFileURL(htmlPath).href
      ],
      { timeout: 6e4, windowsHide: true }
    );
    const buffer = await fs2.readFile(pdfPath);
    return buffer;
  } finally {
    await fs2.rm(tempDir, { recursive: true, force: true });
  }
};
var generateQuotePdf = async (payload = {}) => {
  const { company } = await getCompanyInfo();
  const quoteNumber = String(payload.quote_number || generateQuoteNumber(payload.issued_at)).trim();
  const issuedAt = toDate(payload.issued_at || /* @__PURE__ */ new Date());
  const validUntil = payload.valid_until ? toDate(payload.valid_until) : addDays2(issuedAt, 15);
  const notes = String(payload.notes || "").trim();
  const normalizedItems = normalizeItems(payload.items || []);
  const visibleItems = normalizedItems.slice(0, 20);
  const overflowCount = Math.max(0, normalizedItems.length - visibleItems.length);
  const logoDataUri = await resolveLogoDataUri();
  const html = buildQuoteHtml({
    company,
    quoteNumber,
    customerName: String(payload.customer_name || "\u0639\u0645\u064A\u0644 \u0646\u0642\u062F\u064A").trim(),
    issuedAt,
    validUntil,
    notes,
    items: visibleItems,
    logoDataUri,
    overflowCount
  });
  const buffer = await renderHtmlToPdf(html);
  return { buffer, quoteNumber };
};

