import crypto2 from "crypto";
var ALGORITHM = "aes-256-gcm";
var backupKeySecret = process.env.BACKUP_ENCRYPTION_KEY || "agoouz_default_backup_key_2026";
var ENCRYPTION_KEY = crypto2.scryptSync(
  backupKeySecret,
  "salt_al_ajouz_v2",
  // Changed salt for GCM
  32
);
var encrypt = (text) => {
  const iv = crypto2.randomBytes(12);
  const cipher = crypto2.createCipheriv(ALGORITHM, ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, "utf8", "hex");
  encrypted += cipher.final("hex");
  const authTag = cipher.getAuthTag().toString("hex");
  return iv.toString("hex") + ":" + authTag + ":" + encrypted;
};
var decrypt = (text) => {
  const textParts = text.split(":");
  if (textParts.length === 2) {
    const legacyAlgorithm = "aes-256-cbc";
    const legacyKey = crypto2.scryptSync(
      process.env.BACKUP_ENCRYPTION_KEY || "bin_al_ajouz_erp_secret_salt_2026",
      "salt_al_ajouz",
      32
    );
    const iv2 = Buffer.from(textParts.shift(), "hex");
    const encryptedText2 = Buffer.from(textParts.join(":"), "hex");
    const decipher2 = crypto2.createDecipheriv(legacyAlgorithm, legacyKey, iv2);
    let decrypted2 = decipher2.update(encryptedText2, "hex", "utf8");
    decrypted2 += decipher2.final("utf8");
    return decrypted2;
  }
  if (textParts.length < 3) {
    throw new Error("\u0635\u064A\u063A\u0629 \u0627\u0644\u062A\u0634\u0641\u064A\u0631 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D\u0629 \u0623\u0648 \u0627\u0644\u0645\u0644\u0641 \u062A\u0627\u0644\u0641");
  }
  const iv = Buffer.from(textParts.shift(), "hex");
  const authTag = Buffer.from(textParts.shift(), "hex");
  const encryptedText = Buffer.from(textParts.join(":"), "hex");
  const decipher = crypto2.createDecipheriv(ALGORITHM, ENCRYPTION_KEY, iv);
  decipher.setAuthTag(authTag);
  let decrypted = decipher.update(encryptedText, "hex", "utf8");
  decrypted += decipher.final("utf8");
  return decrypted;
};

