var getPermissions = async () => (await query(`SELECT * FROM permissions ORDER BY module, name_ar`)).rows;
var getRolePermissions = async (roleId) => (await query(`SELECT permission_id FROM role_permissions WHERE role_id = $1`, [roleId])).rows.map(
  (r) => r.permission_id
);
var updateRolePermissions = async (roleId, permissionIds) => {
  const client = await getClient();
  try {
    await client.query("BEGIN");
    await client.query(`DELETE FROM role_permissions WHERE role_id = $1`, [roleId]);
    if (permissionIds && permissionIds.length > 0) {
      const values = [];
      const placeholders = [];
      permissionIds.forEach((permId, idx) => {
        values.push(roleId, permId);
        placeholders.push(`($${idx * 2 + 1}, $${idx * 2 + 2})`);
      });
      const sql = `INSERT INTO role_permissions (role_id, permission_id) VALUES ${placeholders.join(", ")}`;
      await client.query(sql, values);
    }
    await client.query("COMMIT");
    return { success: true };
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
};

