init_pool();
import fs3 from "fs/promises";
import path4 from "path";
var BACKUP_DIR = path4.join(process.cwd(), "backups");
var resolveBackupFilePath = (name) => {
  const rawName = String(name || "");
  const fileName = path4.basename(rawName);
  if (!fileName || fileName !== rawName || fileName.includes("..") || !fileName.endsWith(".json")) {
    throw new AppError("Invalid backup file name", 400);
  }
  const resolved = path4.resolve(BACKUP_DIR, fileName);
  const backupRoot = path4.resolve(BACKUP_DIR) + path4.sep;
  if (!resolved.startsWith(backupRoot)) {
    throw new AppError("Invalid backup file name", 400);
  }
  return resolved;
};
