var fitLinearRegression = (y) => {
  const n = y.length;
  if (n === 0) return { slope: 0, intercept: 0 };
  let sumX = 0;
  let sumY = 0;
  for (let i2 = 0; i2 < n; i2++) {
    sumX += i2 + 1;
    sumY += y[i2];
  }
  const meanX = sumX / n;
  const meanY = sumY / n;
  let num = 0;
  let den = 0;
  for (let i2 = 0; i2 < n; i2++) {
    const x = i2 + 1;
    num += (x - meanX) * (y[i2] - meanY);
    den += (x - meanX) * (x - meanX);
  }
  const slope = den === 0 ? 0 : num / den;
  const intercept = meanY - slope * meanX;
  return { slope, intercept };
};
